`timescale 1ns / 1ps

module FU_ALU(
    input clk, EN,
    input[3:0] ALUControl,
    input[31:0] ALUA, ALUB,
    output[31:0] res,
    output zero, overflow,
    output finish
);

    reg state;
    assign finish = state == 1'b1;
    initial begin
        state = 0;
    end

    localparam ALU_ADD  = 4'b0001;
    localparam ALU_SUB  = 4'b0010;
    localparam ALU_AND  = 4'b0011;
    localparam ALU_OR   = 4'b0100;
    localparam ALU_XOR  = 4'b0101;
    localparam ALU_SLL  = 4'b0110;
    localparam ALU_SRL  = 4'b0111;
    localparam ALU_SLT  = 4'b1000;
    localparam ALU_SLTU = 4'b1001;
    localparam ALU_SRA  = 4'b1010;
    localparam ALU_Ap4  = 4'b1011;
    localparam ALU_Bout = 4'b1100;

    reg[3:0] ALUControl_reg;
    reg[31:0] ALUA_reg, ALUB_reg;

    always @(posedge clk) begin
        if (EN & ~state) begin
            state <= 1'b1;
            ALUControl_reg <= ALUControl;
            ALUA_reg <= ALUA;
            ALUB_reg <= ALUB;
        end
        else if (state) begin
            state <= 1'b0;
        end
    end

    wire[31:0] res_ADD  = ALUA_reg + ALUB_reg;
    wire[31:0] res_SUB  = ALUA_reg - ALUB_reg;
    wire[31:0] res_AND  = ALUA_reg & ALUB_reg;
    wire[31:0] res_OR   = ALUA_reg | ALUB_reg;
    wire[31:0] res_XOR  = ALUA_reg ^ ALUB_reg;
    wire[31:0] res_SLL  = ALUA_reg << ALUB_reg[4:0];
    wire[31:0] res_SRL  = ALUA_reg >> ALUB_reg[4:0];
    wire[31:0] res_SLT  = ($signed(ALUA_reg) < $signed(ALUB_reg)) ? 32'd1 : 32'd0;
    wire[31:0] res_SLTU = (ALUA_reg < ALUB_reg) ? 32'd1 : 32'd0;
    wire[31:0] res_SRA  = $signed(ALUA_reg) >>> ALUB_reg[4:0];
    wire[31:0] res_Ap4  = ALUA_reg + 32'd4;
    wire[31:0] res_Bout = ALUB_reg;

    assign res = ALUControl_reg == ALU_ADD  ? res_ADD  :
                 ALUControl_reg == ALU_SUB  ? res_SUB  :
                 ALUControl_reg == ALU_AND  ? res_AND  :
                 ALUControl_reg == ALU_OR   ? res_OR   :
                 ALUControl_reg == ALU_XOR  ? res_XOR  :
                 ALUControl_reg == ALU_SLL  ? res_SLL  :
                 ALUControl_reg == ALU_SRL  ? res_SRL  :
                 ALUControl_reg == ALU_SLT  ? res_SLT  :
                 ALUControl_reg == ALU_SLTU ? res_SLTU :
                 ALUControl_reg == ALU_SRA  ? res_SRA  :
                 ALUControl_reg == ALU_Ap4  ? res_Ap4  :
                 ALUControl_reg == ALU_Bout ? res_Bout : 32'b0;

    assign zero = ~|res;

    assign overflow = (ALUControl_reg == ALU_ADD &
                       (ALUA_reg[31] == ALUB_reg[31]) & (res[31] != ALUA_reg[31])) |
                      (ALUControl_reg == ALU_SUB &
                       (ALUA_reg[31] != ALUB_reg[31]) & (res[31] != ALUA_reg[31]));

endmodule

`timescale 1ns / 1ps

module FU_mul(
    input clk, EN,
    input[31:0] A, B,
    output[31:0] res,
    output finish
);

    reg[6:0] state;
    assign finish = state[0] == 1'b1;
    initial begin
        state = 0;
    end

    reg[31:0] A_reg, B_reg;
    wire[63:0] mulres;

    multiplier mul(.A(A_reg), .B(B_reg), .P(mulres));

    always @(posedge clk) begin
        if (EN & ~|state) begin
            state <= 7'b100_0000;
            A_reg <= A;
            B_reg <= B;
        end
        else begin
            state <= {1'b0, state[6:1]};
        end
    end

    assign res = mulres[31:0];

endmodule

`timescale 1ns / 1ps

// Behavioral model of the multiplier IP.
// Combinational 32x32 -> 64 multiplication; FU_mul uses the lower 32 bits.
module multiplier(
    input[31:0] A,
    input[31:0] B,
    output[63:0] P
);

    assign P = $signed(A) * $signed(B);

endmodule

`timescale 1ns / 1ps

module FU_div(
    input clk, EN,
    input[31:0] A, B,
    output[31:0] res,
    output finish
);

    wire res_valid;
    wire[63:0] divres;

    reg state;
    assign finish = res_valid & state;
    initial begin
        state = 0;
    end

    reg A_valid, B_valid;
    reg[31:0] A_reg, B_reg;

    initial begin
        A_valid = 0;
        B_valid = 0;
    end

    divider div(
        .aclk(clk),
        .s_axis_dividend_tvalid(A_valid),
        .s_axis_dividend_tdata(A_reg),
        .s_axis_divisor_tvalid(B_valid),
        .s_axis_divisor_tdata(B_reg),
        .m_axis_dout_tvalid(res_valid),
        .m_axis_dout_tdata(divres)
    );

    always @(posedge clk) begin
        if (EN & ~state) begin
            state <= 1'b1;
            A_reg <= A;
            B_reg <= B;
            A_valid <= 1'b1;
            B_valid <= 1'b1;
        end
        else if (res_valid) begin
            state <= 1'b0;
            A_valid <= 1'b0;
            B_valid <= 1'b0;
        end
        else begin
            A_valid <= 1'b0;
            B_valid <= 1'b0;
        end
    end

    assign res = divres[63:32];

endmodule

`timescale 1ns / 1ps

// Behavioral model of the divider IP (AXI4-Stream style handshake).
// Accepts dividend/divisor when both tvalid are asserted, then produces
// {quotient, remainder} on m_axis_dout_tdata with tvalid high for one cycle.
module divider(
    input aclk,
    input s_axis_dividend_tvalid,
    input[31:0] s_axis_dividend_tdata,
    input s_axis_divisor_tvalid,
    input[31:0] s_axis_divisor_tdata,
    output reg m_axis_dout_tvalid,
    output reg[63:0] m_axis_dout_tdata
);

    localparam LATENCY = 8;

    reg busy;
    reg[3:0] cnt;
    reg[31:0] dividend, divisor;

    initial begin
        busy = 0;
        cnt = 0;
        m_axis_dout_tvalid = 0;
        m_axis_dout_tdata = 0;
    end

    always @(posedge aclk) begin
        if (m_axis_dout_tvalid) begin
            m_axis_dout_tvalid <= 1'b0;
        end

        if (~busy & s_axis_dividend_tvalid & s_axis_divisor_tvalid) begin
            busy <= 1'b1;
            cnt <= 0;
            dividend <= s_axis_dividend_tdata;
            divisor <= s_axis_divisor_tdata;
        end
        else if (busy) begin
            if (cnt == LATENCY - 1) begin
                busy <= 1'b0;
                m_axis_dout_tvalid <= 1'b1;
                if (divisor == 32'b0) begin
                    // RISC-V: division by zero yields quotient = -1, remainder = dividend
                    m_axis_dout_tdata <= {32'hFFFFFFFF, dividend};
                end
                else if (dividend == 32'h80000000 && divisor == 32'hFFFFFFFF) begin
                    // RISC-V: signed overflow yields quotient = dividend, remainder = 0
                    m_axis_dout_tdata <= {32'h80000000, 32'b0};
                end
                else begin
                    m_axis_dout_tdata <= {$signed(dividend) / $signed(divisor),
                                          $signed(dividend) % $signed(divisor)};
                end
            end
            else begin
                cnt <= cnt + 1'b1;
            end
        end
    end

endmodule

`timescale 1ns / 1ps

module FU_jump(
	input clk, EN, JALR,
	input[3:0] cmp_ctrl,
	input[31:0] rs1_data, rs2_data, imm, PC,
	output[31:0] PC_jump, PC_wb,
	output is_jump, finish
);

	wire cmp_res;
    reg state;
    assign finish = state == 1'b1;
	initial begin
        state = 0;
    end

	reg JALR_reg;
	reg[3:0] cmp_ctrl_reg = 0;
	reg[31:0] rs1_data_reg = 0, rs2_data_reg = 0, imm_reg = 0, PC_reg = 0;

    always @(posedge clk) begin
        if (EN & ~state) begin
            state <= 1'b1;
            JALR_reg <= JALR;
            cmp_ctrl_reg <= cmp_ctrl;
            rs1_data_reg <= rs1_data;
            rs2_data_reg <= rs2_data;
            imm_reg <= imm;
            PC_reg <= PC;
        end
        else if (state) begin
            state <= 1'b0;
        end
    end

    cmp_32 cmp(.a(rs1_data_reg), .b(rs2_data_reg), .ctrl(cmp_ctrl_reg[3:1]), .c(cmp_res));

    wire[31:0] jump_base;
    MUX2T1_32 mux_jump_base(.I0(PC_reg), .I1(rs1_data_reg), .s(JALR_reg), .o(jump_base));

    add_32 add_jump(.a(jump_base), .b(imm_reg), .c(PC_jump));
    add_32 add_wb(.a(PC_reg), .b(32'd4), .c(PC_wb));

    assign is_jump = cmp_ctrl_reg[0] | cmp_res;

endmodule

`timescale 1ns / 1ps

module FU_mem(
    input clk, EN, mem_w,
    input[2:0] bhw,
    input[31:0] rs1_data, rs2_data, imm,
    output[31:0] mem_data,
    output finish
);

    reg[1:0] state;
    assign finish = state[0] == 1'b1;
    initial begin
        state = 0;
    end

    reg mem_w_reg;
    reg[2:0] bhw_reg;
    reg[31:0] rs1_data_reg, rs2_data_reg, imm_reg;

    wire[31:0] addr;

    add_32 add_addr(.a(rs1_data_reg), .b(imm_reg), .c(addr));

    RAM_B ram(
        .addra(addr),
        .clka(clk),
        .dina(rs2_data_reg),
        .wea(mem_w_reg & state[1]),
        .douta(mem_data),
        .mem_u_b_h_w(bhw_reg),
        .finish(finish)
    );

    always @(posedge clk) begin
        if (EN & ~|state) begin
            state <= 2'b10;
            mem_w_reg <= mem_w;
            bhw_reg <= bhw;
            rs1_data_reg <= rs1_data;
            rs2_data_reg <= rs2_data;
            imm_reg <= imm;
        end
        else begin
            state <= {1'b0, state[1]};
        end
    end

endmodule

`timescale 1ns / 1ps

module RAM_B(
    input [31:0] addra,
    input clka,      // normal clock
    input[31:0] dina,
    input wea, 
    output[31:0] douta,
    input[2:0] mem_u_b_h_w,
    input finish
);

    localparam SIZE = 512;
    localparam ADDR_LINE = $clog2(SIZE);
    localparam SIM_UART_ADDR = 32'h10000000;

    reg[7:0] data[0:SIZE-1];

    initial	begin
        $readmemh("ram.mem", data);
    end

    wire uart_w = wea & (addra == SIM_UART_ADDR);
    wire ram_w  = wea & (addra != SIM_UART_ADDR) & ~|addra[31:ADDR_LINE];
    wire[ADDR_LINE-1:0] addr = addra[ADDR_LINE-1:0];

    // write: byte / halfword / word, little endian
    always @ (negedge clka) begin
        if (ram_w) begin
            data[addr] <= dina[7:0];
            if (mem_u_b_h_w[0] | mem_u_b_h_w[1])
                data[addr + 1] <= dina[15:8];
            if (mem_u_b_h_w[1]) begin
                data[addr + 2] <= dina[23:16];
                data[addr + 3] <= dina[31:24];
            end
        end
    end

    // read: word / halfword / byte with sign or zero extension
    assign douta = (addra == SIM_UART_ADDR) ? 32'b0 :
        |addra[31:ADDR_LINE] ? 32'b0 :
        mem_u_b_h_w[1] ? {data[addr + 3], data[addr + 2],
                    data[addr + 1], data[addr]} :
        mem_u_b_h_w[0] ? {mem_u_b_h_w[2] ? 16'b0 : {16{data[addr + 1][7]}},
                    data[addr + 1], data[addr]} :
        {mem_u_b_h_w[2] ? 24'b0 : {24{data[addr][7]}}, data[addr]};

    // UART simulation: latch the character written to SIM_UART_ADDR,
    // print it when the store retires (finish).
    reg uart_addr_valid;
    reg[7:0] uart_char;

    initial begin
        uart_addr_valid = 0;
        uart_char = 0;
    end

    always @ (negedge clka) begin
        if (uart_w) begin
            uart_addr_valid <= 1'b1;
            uart_char <= dina[7:0];
        end
        else if (finish & uart_addr_valid) begin
            $write("%c", uart_char);
            uart_addr_valid <= 1'b0;
        end
    end

endmodule

`timescale 1ns / 1ps

module ImmGen(
            input  wire [2:0] ImmSel,
            (* DONT_TOUCH = "1" *)  input  wire [31:0] inst_field,
            output[31:0] Imm_out
    );
    parameter Imm_type_I = 3'b001;
    parameter Imm_type_B = 3'b010;
    parameter Imm_type_J = 3'b011;
    parameter Imm_type_S = 3'b100;
    parameter Imm_type_U = 3'b101;

    wire I = ImmSel == Imm_type_I;
    wire B = ImmSel == Imm_type_B;
    wire J = ImmSel == Imm_type_J;
    wire S = ImmSel == Imm_type_S;
    wire U = ImmSel == Imm_type_U;

    wire[31:0] Imm_I = {{21{inst_field[31]}}, inst_field[30:20]};
    wire[31:0] Imm_B = {{20{inst_field[31]}}, inst_field[7], inst_field[30:25],
                        inst_field[11:8], 1'b0};
    wire[31:0] Imm_J = {{12{inst_field[31]}}, inst_field[19:12], inst_field[20],
                        inst_field[30:21], 1'b0};
    wire[31:0] Imm_S = {{21{inst_field[31]}}, inst_field[30:25], inst_field[11:7]};
    wire[31:0] Imm_U = {inst_field[31:12], 12'b0};

    assign Imm_out = I ? Imm_I :
                     B ? Imm_B :
                     J ? Imm_J :
                     S ? Imm_S :
                     U ? Imm_U : 32'b0;

endmodule

