`timescale 1ns / 1ps
`include "CtrlDefine.vh"

// Reservation station for one functional unit type.
// Entry layout (see CtrlDefine.vh):
//   | BUSY | OP | Q1 | Q2 | V1 | V2 | A | PC |
// An 8-bit tag {FU[2:0], index+1} identifies each entry on the CDB and in
// the RAT; 8'b0 means "no dependency".
// An entry is freed only when its result is broadcast on the CDB, so a tag
// is never reused while an older instruction still references it.
module RS #(
    parameter FU = `FU_ALU,
    parameter num = 3
)(
    input clk,
    input rst,

    // issue interface
    input selected,             // allocate an entry for the instr in IS
    output [7:0] free_rs,       // tag of a free entry, 0 if none
    input [4:0] op,
    input [7:0] Qj, Qk,         // RAT lookup results (0 = value already valid)
    input [31:0] Vj, Vk,        // operand values (register file / imm / PC)
    input [31:0] A,             // immediate
    input [31:0] pc_IS,         // PC of the instr in IS

    // dispatch interface (to FU)
    output en_FU,               // one-cycle pulse
    output [31:0] vj, vk,
    output [4:0] op_out,
    output [31:0] A_o,
    output [31:0] pc_FU,        // PC of the instr currently in the FU
    output reg [7:0] cdb_rs_rd, // tag of the instr currently in the FU

    // CDB broadcast
    input [7:0] cdb_rs_num,
    input [31:0] cdb_data,

    output [31:0] pc_debug
);

    reg [159:0] entry [0:num-1];
    reg [num-1:0] dispatched;   // entry sent to FU, waiting for CDB
    reg fu_busy;                // FU is executing an instruction
    reg [31:0] pc_reg;

    integer i;

    function [7:0] tag_of;
        input integer idx;
        tag_of = (FU << 5) | (idx + 1);
    endfunction

    // ---- free entry allocation (lowest index first) ----
    reg [7:0] free_tag;
    integer free_idx;
    always @ (*) begin
        free_tag = 8'b0;
        free_idx = 0;
        for (i = num - 1; i >= 0; i = i - 1) begin
            if (~entry[i][`BUSY]) begin
                free_tag = tag_of(i);
                free_idx = i;
            end
        end
    end
    assign free_rs = free_tag;

    // ---- ready entry selection (lowest index first) ----
    integer disp_idx;
    reg disp_found;
    always @ (*) begin
        disp_found = 1'b0;
        disp_idx = 0;
        for (i = num - 1; i >= 0; i = i - 1) begin
            if (entry[i][`BUSY] & ~dispatched[i]
                & ~|entry[i][`Q1_H:`Q1_L] & ~|entry[i][`Q2_H:`Q2_L]) begin
                disp_found = 1'b1;
                disp_idx = i;
            end
        end
    end

    assign en_FU  = disp_found & ~fu_busy;
    assign vj     = entry[disp_idx][`V1_H:`V1_L];
    assign vk     = entry[disp_idx][`V2_H:`V2_L];
    assign op_out = entry[disp_idx][`OP_H:`OP_L];
    assign A_o    = entry[disp_idx][`A_H:`A_L];
    assign pc_FU  = pc_reg;
    assign pc_debug = pc_reg;

    // operand values captured at issue; if the needed tag is being broadcast
    // on the CDB this very cycle, take the CDB value directly
    wire qj_hit = |Qj & (Qj == cdb_rs_num);
    wire qk_hit = |Qk & (Qk == cdb_rs_num);
    wire [7:0]  Qj_adj = qj_hit ? 8'b0 : Qj;
    wire [7:0]  Qk_adj = qk_hit ? 8'b0 : Qk;
    wire [31:0] Vj_adj = qj_hit ? cdb_data : Vj;
    wire [31:0] Vk_adj = qk_hit ? cdb_data : Vk;

    always @ (posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < num; i = i + 1) begin
                entry[i] <= 160'b0;
            end
            dispatched <= {num{1'b0}};
            fu_busy <= 1'b0;
            cdb_rs_rd <= 8'b0;
            pc_reg <= 32'b0;
        end
        else begin
            // dispatch to FU
            if (en_FU) begin
                dispatched[disp_idx] <= 1'b1;
                fu_busy <= 1'b1;
                cdb_rs_rd <= tag_of(disp_idx);
                pc_reg <= entry[disp_idx][`PC_H:`PC_L];
            end
            else if (fu_busy & |cdb_rs_num & (cdb_rs_num == cdb_rs_rd)) begin
                fu_busy <= 1'b0;
            end

            for (i = 0; i < num; i = i + 1) begin
                if (selected & |free_rs & (i == free_idx)) begin
                    // allocate: {PC, A, V2, V1, Q2, Q1, OP, BUSY}
                    entry[i] <= {pc_IS, A, Vk_adj, Vj_adj, Qk_adj, Qj_adj, op, 1'b1};
                    dispatched[i] <= 1'b0;
                end
                else begin
                    // CDB broadcast retires the entry it corresponds to
                    if (entry[i][`BUSY] & |cdb_rs_num & (cdb_rs_num == tag_of(i))) begin
                        entry[i][`BUSY] <= 1'b0;
                        dispatched[i] <= 1'b0;
                    end
                    // operand snoop
                    if (entry[i][`BUSY] & ~dispatched[i]) begin
                        if (|entry[i][`Q1_H:`Q1_L] & (entry[i][`Q1_H:`Q1_L] == cdb_rs_num)) begin
                            entry[i][`V1_H:`V1_L] <= cdb_data;
                            entry[i][`Q1_H:`Q1_L] <= 8'b0;
                        end
                        if (|entry[i][`Q2_H:`Q2_L] & (entry[i][`Q2_H:`Q2_L] == cdb_rs_num)) begin
                            entry[i][`V2_H:`V2_L] <= cdb_data;
                            entry[i][`Q2_H:`Q2_L] <= 8'b0;
                        end
                    end
                end
            end
        end
    end

endmodule

`timescale 1ns / 1ps
`include "CtrlDefine.vh"
module  RV32core(
        input debug_en,  // debug enable
        input debug_step,  // debug step clock
        input [6:0] debug_addr,  // debug address
        output[31:0] debug_data,  // debug data
        output[31:0] wb_addr,
        output[31:0] wb_data,
        output reg [31:0] clk_counter,
        input clk,  // main clock
        input rst,  // synchronous reset
        input interrupter  // interrupt source, for future use
    );

    wire debug_clk;
    wire[31:0] debug_regs;
    reg[31:0] Test_signal;
	assign debug_data = debug_addr[5] ? Test_signal : debug_regs;

    debug_clk clock(.clk(clk),.debug_en(debug_en),.debug_step(debug_step),.debug_clk(debug_clk));

    wire PC_EN_IF, IS_EN, FU_ALU_EN, FU_mem_EN, FU_mul_EN, FU_div_EN, FU_jump_EN;
    wire RegWrite_ctrl, ALUSrcA_ctrl, ALUSrcB_ctrl, mem_w_ctrl;
    wire[2:0] ImmSel_ctrl, bhw_ctrl, DatatoReg_ctrl;
    wire[3:0] ALUControl_ctrl;
    wire[4:0] Jump_ctrl;
    wire[4:0] rs1_addr_ctrl, rs2_addr_ctrl, rd_ctrl;
    wire[31:0] PC_ctrl, imm_ctrl;


    wire [31:0] PC_IF, next_PC_IF, PC_4_IF, inst_IF;

    wire[31:0]inst_IS, PC_IS, Imm_out_IS;

    wire[31:0]rs1_data_RO, rs2_data_RO, ALUA_RO, ALUB_RO;

    wire FU_ALU_finish, FU_mem_finish, FU_mul_finish, FU_div_finish, FU_jump_finish, is_jump_FU;
    wire[31:0]ALUout_FU, mem_data_FU, mulres_FU, divres_FU, PC_jump_FU, PC_wb_FU;

    wire[31:0]ALUout_WB, mem_data_WB, mulres_WB, divres_WB, PC_wb_WB, wt_data_WB;

    wire  ALU_use, MEM_use, MUL_use, DIV_use, JUMP_use;
    wire rs_rd_w_en, rs_rd_w_en_ALU, rs_rd_w_en_MEM, rs_rd_w_en_DIV, rs_rd_w_en_MUL, rs_rd_w_en_JUMP;
	wire  [4:0]R_addr_rd;
	wire [7:0] rs_num_rd, rs_num_A, rs_num_B, rs_num_rd_ALU, rs_num_rd_MEM, rs_num_rd_DIV, rs_num_rd_MUL, rs_num_rd_JUMP;
	wire [4:0] op_IS;

	wire [31:0] ALU_src1, ALU_src2, ALU_pc, MUL_src1, MUL_src2, MUL_pc, DIV_src1, DIV_src2, DIV_pc, JUMP_src1, JUMP_src2, JUMP_pc, JUMP_pc_cal, MEM_src1, MEM_src2, MEM_pc, JUMP_A, MEM_A;
	wire [4:0] ALU_op, JUMP_op, MEM_op;
	wire [7:0] ALU_rs_rd, MUL_rs_rd,DIV_rs_rd, JUMP_rs_rd, MEM_rs_rd;

	reg [31:0]ALUout_WB_, mem_data_WB_, mulres_WB_, divres_WB_, PC_wb_WB_, wt_data_WB_;
	reg [7:0] rs_ALU_WB_, rs_MEM_WB_, rs_MUL_WB_, rs_DIV_WB_, rs_JUMP_WB_;
	reg [31:0] pc_ALU_WB_, pc_MEM_WB_, pc_MUL_WB_, pc_DIV_WB_, pc_JUMP_WB_;

	// cdb broadcast, target RS entry and data
	wire [7:0] cdb_rs_num;
	wire [31:0] cdb_data;

	reg ctrl_stall=0;
    wire FU_stall;

    wire issue_ok;       // instr in IS can be issued this cycle
    wire jump_taken;     // jump/branch resolves to taken this cycle


    // IF
    assign jump_taken = FU_jump_finish & is_jump_FU;
    assign PC_EN_IF = ~FU_stall & (~ctrl_stall | jump_taken);

    REG32 REG_PC(.clk(debug_clk),.rst(rst),.CE(PC_EN_IF),.D(next_PC_IF),.Q(PC_IF));

    add_32 add_IF(.a(PC_IF),.b(32'd4),.c(PC_4_IF));

    MUX2T1_32 mux_IF(.I0(PC_4_IF),.I1(PC_jump_FU),.s(jump_taken),.o(next_PC_IF));

    ROM_D inst_rom(.a(PC_IF[10:2]),.spo(inst_IF));


    //Issue
    assign IS_EN = ~FU_stall & (~ctrl_stall | jump_taken);

    REG_IF_IS reg_IF_IS(.clk(debug_clk),.rst(rst),.EN(IS_EN),
        .flush(jump_taken),.PCOUT(PC_IF),.IR(inst_IF),
        .IR_IS(inst_IS),.PCurrent_IS(PC_IS));

    ImmGen imm_gen(.ImmSel(ImmSel_ctrl),.inst_field(inst_IS),.Imm_out(Imm_out_IS));

    CtrlUnit ctrl(
        .inst(inst_IS),

        .ImmSel(ImmSel_ctrl),
        .rs1_ctrl(rs1_addr_ctrl),.rs2_ctrl(rs2_addr_ctrl), .dst_ctrl(rd_ctrl) ,
        .ALU_use_PC(ALUSrcA_ctrl),.ALU_use_imm(ALUSrcB_ctrl),

        .op(op_IS),
        .ALU_use(ALU_use), .MEM_use(MEM_use), .MUL_use(MUL_use), .DIV_use(DIV_use), .JUMP_use(JUMP_use)
    );

    // structural hazard: the RS of the needed FU has no free entry
    assign FU_stall = (ALU_use  & ~|rs_num_rd_ALU)  |
                      (MEM_use  & ~|rs_num_rd_MEM)  |
                      (MUL_use  & ~|rs_num_rd_MUL)  |
                      (DIV_use  & ~|rs_num_rd_DIV)  |
                      (JUMP_use & ~|rs_num_rd_JUMP) ;

    // no ROB: once a jump/branch is issued, stop issuing until it resolves
    always @(posedge debug_clk or posedge rst) begin
        if (rst) begin
            ctrl_stall <= 1'b0;
        end
        else if (FU_jump_finish) begin
            ctrl_stall <= 1'b0;
        end
        else if (issue_ok & JUMP_use) begin
            ctrl_stall <= 1'b1;
        end
    end

    assign issue_ok = ~ctrl_stall & ~FU_stall;

    // allocated free RS entry, if any
    assign rs_num_rd = ALU_use  ? rs_num_rd_ALU  :
                       MEM_use  ? rs_num_rd_MEM  :
                       MUL_use  ? rs_num_rd_MUL  :
                       DIV_use  ? rs_num_rd_DIV  :
                       JUMP_use ? rs_num_rd_JUMP : 8'b0;

    // does this instr write a register? if so the RAT records its RS entry
    assign rs_rd_w_en = issue_ok & |rd_ctrl;


    // u can integrate RAT into registers
    Regs register(.clk(debug_clk),.rst(rst),

       // for tomasulo IS
	   .rs_rd_w_en(rs_rd_w_en),
	   .R_addr_rd(rd_ctrl),    // target reg
	   .rs_num_rd(rs_num_rd),  // free RS entry, RAT[target reg] = free RS entry
	   .rs_num_A(rs_num_A),    // Qj
	   .rs_num_B(rs_num_B),    // Qk

        // cdb broadcast
        .cdb_rs_num(cdb_rs_num), 
		.cdb_data(cdb_data),

        .R_addr_A(rs1_addr_ctrl),.rdata_A(rs1_data_RO),
        .R_addr_B(rs2_addr_ctrl),.rdata_B(rs2_data_RO),
//        .L_S(RegWrite_ctrl),.Wt_addr(rd_ctrl),.Wt_data(wt_data_WB),   // cdb broadcast will update register, not here
        .Debug_addr(debug_addr[4:0]),.Debug_regs(debug_regs));

    MUX2T1_32 mux_imm_ALU_RO_A(.I0(rs1_data_RO),.I1(PC_IS),.s(ALUSrcA_ctrl),.o(ALUA_RO));

    MUX2T1_32 mux_imm_ALU_RO_B(.I0(rs2_data_RO),.I1(Imm_out_IS),.s(ALUSrcB_ctrl),.o(ALUB_RO));


    // RS() and LSQ(TBD)
    RS #(.FU(`FU_ALU), .num(3)) rs_alu(
        .clk(debug_clk),
	    .rst(rst),

		.selected(issue_ok & ALU_use),
	    .free_rs(rs_num_rd_ALU),
	    .op(op_IS),
		.Qj(rs_num_A),
		.Qk(rs_num_B),
		.Vj(ALUA_RO),
		.Vk(ALUB_RO),
		.A(Imm_out_IS),
		.pc_IS(PC_IS),

		.en_FU(FU_ALU_EN),
	    .vj(ALU_src1),
	    .vk(ALU_src2),
		.op_out(ALU_op),
		.A_o(/* unused */),
		.pc_FU(ALU_pc),


		.cdb_rs_rd(ALU_rs_rd),
		.cdb_rs_num(cdb_rs_num),
		.cdb_data(cdb_data),


		.pc_debug(/* unused */)
    );

    // For memory access instrs, to ensure in-order memory access:
    // single-entry RS, so loads/stores are issued and dispatched in order
    RS #(.FU(`FU_MEM), .num(1)) rs_mem(
        .clk(debug_clk),
	    .rst(rst),

		.selected(issue_ok & MEM_use),
	    .free_rs(rs_num_rd_MEM),
	    .op(op_IS),
		.Qj(rs_num_A),
		.Qk(rs_num_B),
		.Vj(rs1_data_RO),
		.Vk(rs2_data_RO),
		.A(Imm_out_IS),
		.pc_IS(PC_IS),

		.en_FU(FU_mem_EN),
	    .vj(MEM_src1),
	    .vk(MEM_src2),
		.op_out(MEM_op),
		.A_o(MEM_A),
		.pc_FU(MEM_pc),


		.cdb_rs_rd(MEM_rs_rd),
		.cdb_rs_num(cdb_rs_num),
		.cdb_data(cdb_data),


		.pc_debug(/* unused */)
    );

    RS #(.FU(`FU_MUL), .num(2)) rs_mul(
        .clk(debug_clk),
	    .rst(rst),

		.selected(issue_ok & MUL_use),
	    .free_rs(rs_num_rd_MUL),
	    .op(op_IS),
		.Qj(rs_num_A),
		.Qk(rs_num_B),
		.Vj(rs1_data_RO),
		.Vk(rs2_data_RO),
		.A(32'b0),
		.pc_IS(PC_IS),

		.en_FU(FU_mul_EN),
	    .vj(MUL_src1),
	    .vk(MUL_src2),
		.op_out(/* unused */),
		.A_o(/* unused */),
		.pc_FU(MUL_pc),


		.cdb_rs_rd(MUL_rs_rd),
		.cdb_rs_num(cdb_rs_num),
		.cdb_data(cdb_data),


		.pc_debug(/* unused */)
    );

    RS #(.FU(`FU_DIV), .num(2)) rs_div(
        .clk(debug_clk),
	    .rst(rst),

		.selected(issue_ok & DIV_use),
	    .free_rs(rs_num_rd_DIV),
	    .op(op_IS),
		.Qj(rs_num_A),
		.Qk(rs_num_B),
		.Vj(rs1_data_RO),
		.Vk(rs2_data_RO),
		.A(32'b0),
		.pc_IS(PC_IS),

		.en_FU(FU_div_EN),
	    .vj(DIV_src1),
	    .vk(DIV_src2),
		.op_out(/* unused */),
		.A_o(/* unused */),
		.pc_FU(DIV_pc),


		.cdb_rs_rd(DIV_rs_rd),
		.cdb_rs_num(cdb_rs_num),
		.cdb_data(cdb_data),


		.pc_debug(/* unused */)
    );

    RS #(.FU(`FU_JUMP), .num(1)) rs_jump(
        .clk(debug_clk),
	    .rst(rst),

		.selected(issue_ok & JUMP_use),
	    .free_rs(rs_num_rd_JUMP),
	    .op(op_IS),
		.Qj(rs_num_A),
		.Qk(rs_num_B),
		.Vj(rs1_data_RO),
		.Vk(rs2_data_RO),
		.A(Imm_out_IS),
		.pc_IS(PC_IS),

		.en_FU(FU_jump_EN),
	    .vj(JUMP_src1),
	    .vk(JUMP_src2),
		.op_out(JUMP_op),
		.A_o(JUMP_A),
		.pc_FU(JUMP_pc),


		.cdb_rs_rd(JUMP_rs_rd),
		.cdb_rs_num(cdb_rs_num),
		.cdb_data(cdb_data),


		.pc_debug(/* unused */)
    );


    // FU, just those in lab5
    FU_ALU alu(.clk(debug_clk),.EN(FU_ALU_EN),.finish(FU_ALU_finish),
        .ALUControl(ALU_op == `ALU_AUIPC ? 4'b0001 : ALU_op[3:0]),
        .ALUA(ALU_src1),.ALUB(ALU_src2),.res(ALUout_FU),
        .zero(),.overflow());

    FU_mem mem(.clk(debug_clk),.EN(FU_mem_EN),.finish(FU_mem_finish),
        .mem_w(MEM_op[0]),.bhw(MEM_op[3:1]),.rs1_data(MEM_src1),.rs2_data(MEM_src2),
        .imm(MEM_A),.mem_data(mem_data_FU));

    FU_mul mu(.clk(debug_clk),.EN(FU_mul_EN),.finish(FU_mul_finish),
        .A(MUL_src1),.B(MUL_src2),.res(mulres_FU));

    FU_div du(.clk(debug_clk),.EN(FU_div_EN),.finish(FU_div_finish),
        .A(DIV_src1),.B(DIV_src2),.res(divres_FU));

    FU_jump ju(.clk(debug_clk),.EN(FU_jump_EN),.finish(FU_jump_finish),
        .JALR(JUMP_op[4]),.cmp_ctrl(JUMP_op[3:0]),.rs1_data(JUMP_src1),.rs2_data(JUMP_src2),
        .imm(JUMP_A),.PC(JUMP_pc),.PC_jump(PC_jump_FU),.PC_wb(PC_wb_FU),.is_jump(is_jump_FU));


    // CDB broadcast 
    reg [5:1] done_record; // similar to lab5, when multi-FU finish, we need to choose one and delay others 
    wire [31:0]cdb_pc;  // for debug

    // every finish is captured; one pending result is broadcast per cycle
    // (fixed priority: ALU > MEM > MUL > DIV > JUMP)
    wire sel_ALU  = done_record[`FU_ALU];
    wire sel_MEM  = ~done_record[`FU_ALU] & done_record[`FU_MEM];
    wire sel_MUL  = ~|done_record[`FU_ALU:`FU_MEM] & done_record[`FU_MUL];
    wire sel_DIV  = ~|done_record[`FU_ALU:`FU_MUL] & done_record[`FU_DIV];
    wire sel_JUMP = ~|done_record[`FU_ALU:`FU_DIV] & done_record[`FU_JUMP];

    assign cdb_data = sel_ALU  ? ALUout_WB_  :
                      sel_MEM  ? mem_data_WB_ :
                      sel_MUL  ? mulres_WB_  :
                      sel_DIV  ? divres_WB_  :
                      sel_JUMP ? PC_wb_WB_   : 32'b0;
    assign cdb_rs_num = sel_ALU  ? rs_ALU_WB_  :
                        sel_MEM  ? rs_MEM_WB_  :
                        sel_MUL  ? rs_MUL_WB_  :
                        sel_DIV  ? rs_DIV_WB_  :
                        sel_JUMP ? rs_JUMP_WB_ : 8'b0;
    assign cdb_pc = sel_ALU  ? pc_ALU_WB_  :
                    sel_MEM  ? pc_MEM_WB_  :
                    sel_MUL  ? pc_MUL_WB_  :
                    sel_DIV  ? pc_DIV_WB_  :
                    sel_JUMP ? pc_JUMP_WB_ : 32'b0;

    always @(posedge debug_clk or posedge rst) begin
        if (rst) begin
            done_record <= 5'b0;
            ALUout_WB_ <= 0; mem_data_WB_ <= 0; mulres_WB_ <= 0; divres_WB_ <= 0; PC_wb_WB_ <= 0;
            rs_ALU_WB_ <= 0; rs_MEM_WB_ <= 0; rs_MUL_WB_ <= 0; rs_DIV_WB_ <= 0; rs_JUMP_WB_ <= 0;
            pc_ALU_WB_ <= 0; pc_MEM_WB_ <= 0; pc_MUL_WB_ <= 0; pc_DIV_WB_ <= 0; pc_JUMP_WB_ <= 0;
        end
        else begin
            if (FU_ALU_finish) begin
                ALUout_WB_ <= ALUout_FU; rs_ALU_WB_ <= ALU_rs_rd; pc_ALU_WB_ <= ALU_pc;
                done_record[`FU_ALU] <= 1'b1;
            end
            else if (sel_ALU) done_record[`FU_ALU] <= 1'b0;

            if (FU_mem_finish) begin
                mem_data_WB_ <= mem_data_FU; rs_MEM_WB_ <= MEM_rs_rd; pc_MEM_WB_ <= MEM_pc;
                done_record[`FU_MEM] <= 1'b1;
            end
            else if (sel_MEM) done_record[`FU_MEM] <= 1'b0;

            if (FU_mul_finish) begin
                mulres_WB_ <= mulres_FU; rs_MUL_WB_ <= MUL_rs_rd; pc_MUL_WB_ <= MUL_pc;
                done_record[`FU_MUL] <= 1'b1;
            end
            else if (sel_MUL) done_record[`FU_MUL] <= 1'b0;

            if (FU_div_finish) begin
                divres_WB_ <= divres_FU; rs_DIV_WB_ <= DIV_rs_rd; pc_DIV_WB_ <= DIV_pc;
                done_record[`FU_DIV] <= 1'b1;
            end
            else if (sel_DIV) done_record[`FU_DIV] <= 1'b0;

            if (FU_jump_finish) begin
                PC_wb_WB_ <= PC_wb_FU; rs_JUMP_WB_ <= JUMP_rs_rd; pc_JUMP_WB_ <= JUMP_pc;
                done_record[`FU_JUMP] <= 1'b1;
            end
            else if (sel_JUMP) done_record[`FU_JUMP] <= 1'b0;
        end
    end


    assign wb_addr = cdb_pc;
    assign wb_data = cdb_data;

    always @(posedge debug_clk) begin
        if (rst) begin
            clk_counter <= 0;
        end else begin
            clk_counter <= clk_counter + 32'd1;
        end
    end



endmodule

