args.content:
`timescale 1ns / 1ps

module tb_lab6;
    reg clk, rst;

    wire [31:0] wb_addr, wb_data;
    wire [31:0] clk_counter;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'b0),
        .debug_data(),
        .wb_addr(wb_addr),
        .wb_data(wb_data),
        .clk_counter(clk_counter),
        .clk(clk),
        .rst(rst),
        .interrupter(1'b0)
    );

    initial begin
        clk = 0;
        rst = 1;
        #4 rst = 0;
    end
    always #1 clk = ~clk;

    // trace CDB broadcasts (Tomasulo write-backs)
    always @(posedge clk) begin
        if (!rst && |core.cdb_rs_num)
            $display("[%0d] CDB: pc=%h data=%h rs_tag=%h", $time, wb_addr, wb_data, core.cdb_rs_num);
    end

    integer k;
    initial begin
        #2000;
        $display("---- architectural registers after %0d cycles ----", clk_counter);
        for (k = 1; k < 16; k = k + 1)
            $display("x%0d = %h", k, core.register.register[k]);
        $display("PC_IF = %h", core.PC_IF);
        $finish;
    end

    // X-propagation watchdog on architectural state
    always @(posedge clk) begin
        if (!rst && |core.cdb_rs_num && (^wb_data === 1'bx))
            $display("[%0d] WARNING: X on CDB data", $time);
    end

endmodule

`timescale 1ns / 1ps

module tb_dbg;
    reg clk, rst;
    wire [31:0] wb_addr, wb_data, clk_counter;

    RV32core core(
        .debug_en(1'b0), .debug_step(1'b0), .debug_addr(7'b0), .debug_data(),
        .wb_addr(wb_addr), .wb_data(wb_data), .clk_counter(clk_counter),
        .clk(clk), .rst(rst), .interrupter(1'b0)
    );

    initial begin clk = 0; rst = 1; #4 rst = 0; end
    always #1 clk = ~clk;

    always @(posedge clk) begin
        if (!rst) begin
            $write("[%0d] PC_IF=%h inst_IS=%h PC_IS=%h", $time, core.PC_IF, core.inst_IS, core.PC_IS);
            if (core.issue_ok && (core.ALU_use|core.MEM_use|core.MUL_use|core.DIV_use|core.JUMP_use))
                $write(" ISSUE fu=%b tag=%h", {core.JUMP_use,core.DIV_use,core.MUL_use,core.MEM_use,core.ALU_use}, core.rs_num_rd);
            if (core.FU_ALU_EN) $write(" ALUdisp a=%h b=%h op=%b", core.ALU_src1, core.ALU_src2, core.ALU_op);
            if (core.FU_mem_EN) $write(" MEMdisp a=%h d=%h imm=%h op=%b", core.MEM_src1, core.MEM_src2, core.MEM_A, core.MEM_op);
            if (core.FU_jump_EN) $write(" JMPdisp rs1=%h rs2=%h imm=%h pc=%h op=%b", core.JUMP_src1, core.JUMP_src2, core.JUMP_A, core.JUMP_pc, core.JUMP_op);
            if (core.FU_mul_EN) $write(" MULdisp a=%h b=%h", core.MUL_src1, core.MUL_src2);
            if (core.FU_div_EN) $write(" DIVdisp a=%h b=%h", core.DIV_src1, core.DIV_src2);
            if (|core.cdb_rs_num) $write(" CDB tag=%h data=%h", core.cdb_rs_num, core.cdb_data);
            if (core.FU_jump_finish) $write(" JMPFIN is_jump=%b target=%h", core.is_jump_FU, core.PC_jump_FU);
            $write(" stall=%b%b", core.ctrl_stall, core.FU_stall);
            $display("");
        end
    end

    initial begin
        #300;
        $display("x1=%h x2=%h x4=%h x5=%h x6=%h x7=%h x8=%h x9=%h",
            core.register.register[1], core.register.register[2], core.register.register[4],
            core.register.register[5], core.register.register[6], core.register.register[7],
            core.register.register[8], core.register.register[9]);
        $finish;
    end

endmodule

