cat > /tmp/lab6_probe.v <<'EOF'
`timescale 1ns / 1ps
module tb_probe;
    reg clk, rst;
    RV32core core(
        .debug_en(1'b0), .debug_step(1'b0), .debug_addr(7'b0), .debug_data(),
        .wb_addr(), .wb_data(), .clk_counter(),
        .clk(clk), .rst(rst), .interrupter(1'b0)
    );
    initial begin clk = 0; rst = 1; #4 rst = 0; end
    always #1 clk = ~clk;
    always @(posedge clk) begin
        if (!rst && core.issue_ok && core.MEM_use)
            $display("[%0d] ISSUE MEM inst=%h ImmSel=%b Imm_out_IS=%h rs2_data=%h rs1_data=%h",
                $time, core.inst_IS, core.ImmSel_ctrl, core.Imm_out_IS, core.rs2_data_RO, core.rs1_data_RO);
        if (!rst && core.rs_mem.selected)
            $display("[%0d] RS_MEM alloc: A_in=%h Vk_in=%h Vj_in=%h entry0_after? (next cycle)", $time, core.rs_mem.A, core.rs_mem.Vk, core.rs_mem.Vj);
    end
    // dump entry after allocation
    always @(negedge clk) begin
        if (!rst)
            $display("   [%0d] rs_mem entry0=%h busy=%b", $time, core.rs_mem.entry[0], core.rs_mem.entry[0][0]);
    end
    initial #60 $finish;
endmodule
EOF
