        #2 selected = 1;
        #2 selected = 0;
        #10 $finish;
    end
    always #1 clk = ~clk;
    always @(negedge clk)
        $display("[%0d] entry0=%h free=%h en_FU=%b vk=%h A_o=%h pc_FU=%h",
            $time, dut.entry[0], free_rs, en_FU, vk, A_o, pc_FU);
endmodule
