cat > /tmp/concat_test.v <<'EOF'
`timescale 1ns / 1ps
module concat_test;
    reg [4:0] op;
    reg [7:0] Qj, Qk;
    reg [31:0] Vj, Vk, A, pc_IS;
    wire [159:0] c1 = {pc_IS, A, Vk, Vj, Qk, Qj, op, 1'b1};
    wire [159:0] c2 = {32'd4, 32'd4, 32'd0, 32'd0, 8'd0, 8'd0, 5'b00100, 1'b1};
    reg [159:0] r1;
    initial begin
        op = 5'b00100; Qj = 0; Qk = 0; Vj = 0; Vk = 0; A = 32'd4; pc_IS = 32'd4;
        #1;
